import React from 'react';
import { motion } from './motion';

export default function SectionHeader({ label, title, subtitle, id }) {
  return (
    <motion.header
      id={id}
      className="mb-12 text-center"
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
    >
      {label && (
        <p className="font-mono text-xs uppercase tracking-widest text-accent-cyan mb-3">{label}</p>
      )}
      <h2 className="text-3xl sm:text-4xl font-bold text-gradient mb-4">{title}</h2>
      {subtitle && <p className="text-zinc-400 max-w-2xl mx-auto text-lg">{subtitle}</p>}
    </motion.header>
  );
}
