import React from 'react';
import { motion } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import { Smartphone } from '../ui/icons';
import productsData from '../../content/products.json';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';
import Badge from '../ui/Badge';

function getIcon(name) {
  try {
    return require(`../../img/${name}`);
  } catch {
    return null;
  }
}

export default function ProductsSection({ lang }) {
  const { t } = useTranslation();
  const sorted = [...productsData.products].sort(
    (a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0)
  );

  return (
    <SectionReveal id="products">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelProducts')}
          title={t('sectionProducts')}
          subtitle={t('productsIntro')}
        />

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
          {sorted.map((product, i) => {
            const icon = getIcon(product.icon);
            return (
              <motion.a
                key={product.id}
                href={product.url}
                target="_blank"
                rel="noopener noreferrer"
                className={`glass-panel p-4 flex flex-col items-center text-center hover:border-accent-cyan/30 transition-all focus-ring rounded-2xl ${
                  product.featured ? 'ring-1 ring-accent-cyan/30' : ''
                }`}
                initial={{ opacity: 0, scale: 0.95 }}
                whileInView={{ opacity: 1, scale: 1 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.03 }}
                whileHover={{ y: -4 }}
              >
                {product.featured && (
                  <Badge className="mb-2 text-accent-cyan border-accent-cyan/30 text-[10px]">
                    Featured
                  </Badge>
                )}
                {icon ? (
                  <img src={icon} alt="" className="w-16 h-16 object-contain mb-3" />
                ) : (
                  <Smartphone className="w-12 h-12 text-zinc-600 mb-3" />
                )}
                <span className={`text-xs font-medium text-zinc-300 line-clamp-2 ${lang === 'ar' ? 'arabic-font' : ''}`}>
                  {t(product.titleKey)}
                </span>
              </motion.a>
            );
          })}
        </div>
      </div>
    </SectionReveal>
  );
}
