import React from 'react';
import Navbar from './Navbar';
import Footer from './Footer';

export default function AppShell({ lang, onLangChange, children }) {
  const dir = lang === 'ar' ? 'rtl' : 'ltr';

  return (
    <div className="min-h-screen dark" dir={dir}>
      <Navbar lang={lang} onLangChange={onLangChange} />
      <main>{children}</main>
      <Footer lang={lang} />
    </div>
  );
}
