import React, { useState } from 'react';
import { motion, AnimatePresence } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import techStack from '../../content/tech-stack.json';
import { localized } from '../../utils/content';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';

export default function TechStackSection({ lang }) {
  const { t } = useTranslation();
  const [active, setActive] = useState(techStack.categories[0].id);

  const category = techStack.categories.find((c) => c.id === active);

  return (
    <SectionReveal id="stack" className="bg-elevated/50">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelStack')}
          title={t('sectionStack')}
          subtitle={t('stackIntro')}
        />

        <div className="flex flex-wrap gap-2 justify-center mb-10">
          {techStack.categories.map((cat) => (
            <button
              key={cat.id}
              type="button"
              onClick={() => setActive(cat.id)}
              className={`px-4 py-2 rounded-full text-sm font-mono transition-all focus-ring ${
                active === cat.id
                  ? 'bg-accent-cyan/20 text-accent-cyan border border-accent-cyan/40 shadow-glow'
                  : 'glass-panel text-zinc-400 hover:text-zinc-200'
              }`}
            >
              {localized(cat, lang, 'label')}
            </button>
          ))}
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={active}
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -12 }}
            transition={{ duration: 0.25 }}
            className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"
          >
            {category?.items.map((item) => (
              <div
                key={item.name}
                className="glass-panel p-5 group hover:border-accent-cyan/30 transition-colors"
              >
                <div className="flex justify-between items-center mb-3">
                  <span className="font-semibold group-hover:text-accent-cyan transition-colors">
                    {item.name}
                  </span>
                  <span className="font-mono text-xs text-zinc-500">{item.proficiency}%</span>
                </div>
                <div className="h-1.5 rounded-full bg-white/10 overflow-hidden">
                  <motion.div
                    className="h-full rounded-full bg-gradient-to-r from-accent-blue to-accent-cyan"
                    initial={{ width: 0 }}
                    whileInView={{ width: `${item.proficiency}%` }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.8, ease: 'easeOut' }}
                  />
                </div>
              </div>
            ))}
          </motion.div>
        </AnimatePresence>
      </div>
    </SectionReveal>
  );
}
