import React, { Suspense, lazy } from 'react';
import ReactDOM from 'react-dom';
import { Router, Route } from 'react-router';
import history from './components/mainPage/history';
import HomePage from './pages/HomePage';
import LegacyPageLayout from './components/legacy/LegacyPageLayout';
import './i18n';

// GitHub Pages SPA redirect (see public/404.html)
(function handleGhPagesRedirect(l) {
  if (l.search.length > 1 && l.search[1] === '/') {
    const decoded = l.search
      .slice(1)
      .split('&')
      .map((s) => s.replace(/~and~/g, '&'))
      .join('?');
    window.history.replaceState(null, null, `${l.pathname.slice(0, -1)}${decoded}${l.hash}`);
  }
})(window.location);

const JavaComponent = lazy(() => import('./components/javaCourse/JavaComponent'));
const HibernateComponent = lazy(() => import('./components/hibernateCourse/HibernateComponent'));
const ReactIndexComponent = lazy(() => import('./components/courseTemplate/ReactIndexComponent'));

const withLegacy = (Component) => (props) => (
  <LegacyPageLayout>
    <Suspense fallback={<div className="p-8 text-center text-zinc-600">Loading...</div>}>
      <Component {...props} />
    </Suspense>
  </LegacyPageLayout>
);

const JavaPage = withLegacy(JavaComponent);
const HibernatePage = withLegacy(HibernateComponent);
const ReactPage = withLegacy(ReactIndexComponent);

ReactDOM.render(
  <Router history={history}>
    <Route path="/">
      <Route exact path="/" component={HomePage} />
      <Route path="/react" component={ReactPage} />
      <Route path="/hibernate" component={HibernatePage} />
      <Route path="/java" component={JavaPage} />
    </Route>
  </Router>,
  document.getElementById('root')
);
