import React from 'react';
import { motion } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import { ExternalLink, Github } from '../ui/icons';
import projectsData from '../../content/projects.json';
import { localized } from '../../utils/content';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';
import Badge from '../ui/Badge';
import TerminalWindow from '../ui/TerminalWindow';

export default function FeaturedProjectsSection({ lang }) {
  const { t } = useTranslation();
  const featured = projectsData.projects.filter((p) => p.featured);

  return (
    <SectionReveal id="projects">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelProjects')}
          title={t('sectionProjects')}
          subtitle={t('projectsIntro')}
        />

        <div className="grid md:grid-cols-2 gap-6">
          {featured.map((project, i) => (
            <motion.article
              key={project.id}
              className={`glass-panel p-6 flex flex-col hover:border-accent-cyan/30 transition-all ${
                i === 0 ? 'md:row-span-1' : ''
              }`}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.08 }}
              whileHover={{ y: -4, boxShadow: '0 0 40px rgba(34, 211, 238, 0.12)' }}
            >
              <TerminalWindow title={project.id} className="mb-4 text-xs">
                <span className="text-accent-cyan">$</span> stack{' '}
                {project.stack.join(' · ')}
              </TerminalWindow>

              <h3 className="text-xl font-bold mb-2">{localized(project, lang, 'title')}</h3>
              <p className="text-zinc-400 text-sm flex-grow mb-4">
                {localized(project, lang, 'description')}
              </p>

              <div className="flex flex-wrap gap-2 mb-4">
                {project.metrics.map((m) => (
                  <Badge key={m} className="text-accent-cyan/90 border-accent-cyan/20">
                    {m}
                  </Badge>
                ))}
              </div>

              <div className="flex flex-wrap gap-2 mb-4">
                {project.stack.map((tech) => (
                  <Badge key={tech}>{tech}</Badge>
                ))}
              </div>

              <div className="flex gap-4 mt-auto">
                {project.github && (
                  <a
                    href={project.github}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-sm text-zinc-400 hover:text-accent-cyan focus-ring rounded"
                  >
                    <Github size={16} /> GitHub
                  </a>
                )}
                {project.demo && (
                  <a
                    href={project.demo}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-sm text-accent-cyan hover:underline focus-ring rounded"
                  >
                    <ExternalLink size={16} /> Demo
                  </a>
                )}
              </div>
            </motion.article>
          ))}
        </div>
      </div>
    </SectionReveal>
  );
}
