import React from 'react';
import i18next from 'i18next';

const langs = [
  { code: 'en', label: 'EN' },
  { code: 'fr', label: 'FR' },
  { code: 'ar', label: 'AR' },
];

export default function LanguageSwitcher({ lang, onLangChange }) {
  const setLang = (code) => {
    document.dir = code === 'ar' ? 'rtl' : 'ltr';
    i18next.changeLanguage(code);
    onLangChange(code === 'ar' ? 'ar' : code === 'fr' ? 'fr' : 'en');
  };

  return (
    <div className="flex gap-1 rounded-lg border border-white/10 p-0.5 bg-white/5">
      {langs.map(({ code, label }) => (
        <button
          key={code}
          type="button"
          onClick={() => setLang(code)}
          className={`px-2.5 py-1 text-xs font-mono rounded-md transition-colors focus-ring ${
            (code === 'ar' && lang === 'ar') ||
            (code === 'fr' && lang === 'fr') ||
            (code === 'en' && (lang === 'en' || lang === 'eng'))
              ? 'bg-accent-cyan/20 text-accent-cyan'
              : 'text-zinc-400 hover:text-zinc-200'
          }`}
          aria-pressed={
            (code === 'ar' && lang === 'ar') ||
            (code === 'fr' && lang === 'fr') ||
            (code === 'en' && (lang === 'en' || lang === 'eng'))
          }
        >
          {label}
        </button>
      ))}
    </div>
  );
}
