import React, { useState } from 'react';
import { motion, AnimatePresence } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import { X, ExternalLink } from '../ui/icons';
import certsData from '../../content/certifications.json';
import { localized } from '../../utils/content';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';

function getCertImage(name) {
  try {
    return require(`../../img/${name}`);
  } catch {
    return null;
  }
}

export default function CertificationsSection({ lang }) {
  const { t } = useTranslation();
  const [modal, setModal] = useState(null);

  return (
    <SectionReveal id="certifications" className="bg-elevated/50">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelCerts')}
          title={t('sectionCerts')}
          subtitle={t('certsIntro')}
        />

        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {certsData.certifications.map((cert, i) => {
            const thumb = getCertImage(cert.thumbnail);
            return (
              <motion.button
                key={cert.id}
                type="button"
                className="glass-panel p-4 text-left hover:border-accent-cyan/30 transition-all focus-ring w-full"
                initial={{ opacity: 0, y: 16 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.08 }}
                whileHover={{ y: -4 }}
                onClick={() => setModal(cert)}
              >
                {thumb && (
                  <img
                    src={thumb}
                    alt=""
                    className="w-full h-32 object-contain mb-4 rounded-lg bg-white/5"
                  />
                )}
                <p className="text-xs font-mono text-zinc-500 mb-1">{cert.issuer}</p>
                <h3 className="font-semibold text-sm leading-snug">
                  {localized(cert, lang, 'title')}
                </h3>
              </motion.button>
            );
          })}
        </div>
      </div>

      <AnimatePresence>
        {modal && (
          <motion.div
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setModal(null)}
            role="dialog"
            aria-modal="true"
            aria-labelledby="cert-modal-title"
          >
            <motion.div
              className="glass-panel max-w-lg w-full p-6 relative"
              initial={{ scale: 0.95 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.95 }}
              onClick={(e) => e.stopPropagation()}
            >
              <button
                type="button"
                className="absolute top-4 right-4 text-zinc-400 hover:text-white focus-ring rounded p-1"
                onClick={() => setModal(null)}
                aria-label="Close"
              >
                <X size={20} />
              </button>
              {getCertImage(modal.fullImage) && (
                <img
                  src={getCertImage(modal.fullImage)}
                  alt={localized(modal, lang, 'title')}
                  className="w-full rounded-lg mb-4"
                />
              )}
              <h3 id="cert-modal-title" className="text-xl font-bold mb-2">
                {localized(modal, lang, 'title')}
              </h3>
              <p className="text-zinc-400 text-sm mb-4">{localized(modal, lang, 'description')}</p>
              <a
                href={modal.verifyUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 text-accent-cyan text-sm hover:underline focus-ring rounded"
              >
                <ExternalLink size={16} /> {t('verifyCert')}
              </a>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </SectionReveal>
  );
}
