import React from 'react';

const variants = {
  primary:
    'bg-gradient-to-r from-accent-blue to-accent-cyan text-charcoal font-semibold hover:shadow-glow',
  secondary:
    'glass-panel text-zinc-100 hover:border-accent-cyan/40 hover:shadow-glow',
  ghost: 'text-zinc-300 hover:text-accent-cyan hover:bg-white/5',
};

export default function Button({
  children,
  variant = 'primary',
  href,
  className = '',
  ...props
}) {
  const classes = `inline-flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl text-sm transition-all duration-300 focus-ring ${variants[variant]} ${className}`;

  if (href) {
    return (
      <a href={href} className={classes} {...props}>
        {children}
      </a>
    );
  }

  const { type = 'button', ...buttonProps } = props;
  return (
    <button type={type} className={classes} {...buttonProps}>
      {children}
    </button>
  );
}
