import React from 'react';
import { motion } from './motion';
import { usePrefersReducedMotion } from '../../hooks/usePrefersReducedMotion';

export default function GlowOrb({ className = '', color = 'cyan' }) {
  const reduced = usePrefersReducedMotion();
  const colors = {
    cyan: 'bg-accent-cyan/20',
    blue: 'bg-accent-blue/20',
    purple: 'bg-accent-purple/20',
  };

  return (
    <motion.div
      className={`absolute rounded-full blur-3xl ${colors[color] || colors.cyan} ${className}`}
      animate={reduced ? {} : { scale: [1, 1.1, 1], opacity: [0.4, 0.6, 0.4] }}
      transition={{ duration: 8, repeat: Infinity, ease: 'easeInOut' }}
      aria-hidden="true"
    />
  );
}
