import React from 'react';
import { motion } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import experience from '../../content/experience.json';
import { localized } from '../../utils/content';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';
import Badge from '../ui/Badge';

export default function JourneySection({ lang }) {
  const { t } = useTranslation();

  return (
    <SectionReveal id="journey">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelJourney')}
          title={t('sectionJourney')}
          subtitle={t('journeyIntro')}
        />

        <div className="max-w-3xl mx-auto">
          {experience.milestones.map((item, i) => (
            <motion.div
              key={i}
              className="flex gap-6 pb-12 last:pb-0"
              initial={{ opacity: 0, x: lang === 'ar' ? 24 : -24 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.12 }}
            >
              <div className="flex flex-col items-center">
                <div className="w-4 h-4 rounded-full bg-accent-blue ring-4 ring-accent-blue/20 shrink-0" />
                {i < experience.milestones.length - 1 && (
                  <div className="w-px flex-1 bg-gradient-to-b from-accent-blue/50 to-transparent mt-2 min-h-[80px]" />
                )}
              </div>
              <div className="glass-panel p-6 flex-1 -mt-1">
                <p className="font-mono text-sm text-accent-blue mb-1">{item.year}</p>
                <h3 className="text-xl font-bold mb-1">{localized(item, lang, 'title')}</h3>
                <p className="text-zinc-500 text-sm mb-3">{localized(item, lang, 'company')}</p>
                <p className="text-zinc-400 text-sm mb-4">{localized(item, lang, 'description')}</p>
                <div className="flex flex-wrap gap-2">
                  {item.tags.map((tag) => (
                    <Badge key={tag}>{tag}</Badge>
                  ))}
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </SectionReveal>
  );
}
