import React, { useState } from 'react';
import { motion } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import { Clock, ArrowUpRight } from '../ui/icons';
import articlesData from '../../content/articles.json';
import { localized } from '../../utils/content';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';
import profile from '../../content/profile.json';

const categories = ['All', 'Java', 'Hibernate', 'DevOps', 'Cloud', 'OpenAPI', 'AI'];

export default function ContentSection({ lang }) {
  const { t } = useTranslation();
  const [filter, setFilter] = useState('All');

  const filtered =
    filter === 'All'
      ? articlesData.articles
      : articlesData.articles.filter((a) => a.category === filter);

  return (
    <SectionReveal id="content" className="bg-elevated/50">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelContent')}
          title={t('sectionContent')}
          subtitle={t('contentIntro')}
        />

        <div className="flex flex-wrap gap-2 justify-center mb-10">
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setFilter(cat)}
              className={`px-3 py-1.5 rounded-lg text-sm font-mono focus-ring ${
                filter === cat
                  ? 'bg-accent-purple/20 text-accent-purple border border-accent-purple/40'
                  : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((article, i) => (
            <motion.a
              key={article.id}
              href={article.url || profile.blog}
              target="_blank"
              rel="noopener noreferrer"
              className="glass-panel p-5 block group hover:border-accent-purple/30 transition-all focus-ring rounded-2xl"
              initial={{ opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.05 }}
              whileHover={{ y: -4 }}
            >
              <span className="text-xs font-mono text-accent-purple">{article.category}</span>
              <h3 className="font-semibold text-lg mt-2 mb-2 group-hover:text-accent-cyan transition-colors">
                {localized(article, lang, 'title')}
              </h3>
              <p className="text-zinc-500 text-sm mb-4 line-clamp-2">
                {localized(article, lang, 'excerpt')}
              </p>
              <div className="flex items-center justify-between text-xs text-zinc-500">
                <span className="flex items-center gap-1">
                  <Clock size={12} /> {article.readTime} min
                </span>
                <ArrowUpRight
                  size={14}
                  className="text-accent-cyan opacity-0 group-hover:opacity-100 transition-opacity"
                />
              </div>
            </motion.a>
          ))}
        </div>
      </div>
    </SectionReveal>
  );
}
