import React from 'react';
import { motion } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import { Layers, Server, Cloud, GraduationCap } from '../ui/icons';
import SectionReveal from '../ui/SectionReveal';
import SectionHeader from '../ui/SectionHeader';
import Card from '../ui/Card';
import experience from '../../content/experience.json';
import { localized } from '../../utils/content';

const pillars = [
  { icon: Layers, key: 'pillarArch' },
  { icon: Server, key: 'pillarBackend' },
  { icon: Cloud, key: 'pillarCloud' },
  { icon: GraduationCap, key: 'pillarContent' },
];

export default function AboutSection({ lang }) {
  const { t } = useTranslation();

  return (
    <SectionReveal id="about">
      <div className="section-container">
        <SectionHeader
          label={t('sectionLabelAbout')}
          title={t('sectionAbout')}
          subtitle={t('aboutIntro')}
        />

        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-16">
          {pillars.map(({ icon: Icon, key }, i) => (
            <motion.div
              key={key}
              initial={{ opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.08 }}
            >
              <Card className="h-full">
                <Icon className="w-8 h-8 text-accent-cyan mb-4" aria-hidden="true" />
                <h3 className="font-semibold text-lg mb-2">{t(`${key}Title`)}</h3>
                <p className="text-zinc-400 text-sm">{t(`${key}Desc`)}</p>
              </Card>
            </motion.div>
          ))}
        </div>

        <div className="relative border-l border-white/10 ml-4 space-y-8">
          {experience.milestones.map((item, i) => (
            <motion.div
              key={i}
              className="relative pl-8"
              initial={{ opacity: 0, x: -12 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1 }}
            >
              <span className="absolute -left-1.5 top-1.5 w-3 h-3 rounded-full bg-accent-cyan ring-4 ring-accent-cyan/20" />
              <p className="font-mono text-xs text-accent-cyan mb-1">{item.year}</p>
              <h4 className="font-semibold text-lg">{localized(item, lang, 'title')}</h4>
              <p className="text-zinc-500 text-sm mb-2">{localized(item, lang, 'company')}</p>
              <p className="text-zinc-400 text-sm">{localized(item, lang, 'description')}</p>
            </motion.div>
          ))}
        </div>
      </div>
    </SectionReveal>
  );
}
