import React, { useState, useEffect } from 'react';
import { Menu, X } from '../ui/icons';
import { useTranslation } from 'react-i18next';
import LanguageSwitcher from './LanguageSwitcher';
import logo from '../../img/logo.png';

const links = [
  { href: '#about', key: 'navAbout' },
  { href: '#stack', key: 'navStack' },
  { href: '#projects', key: 'navProjects' },
  { href: '#content', key: 'navContent' },
  { href: '#journey', key: 'navJourney' },
  { href: '#contact', key: 'navContact' },
];

export default function Navbar({ lang, onLangChange }) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled ? 'glass-panel border-b border-white/10 py-3' : 'py-5 bg-transparent'
      }`}
    >
      <nav
        className="section-container flex items-center justify-between"
        aria-label="Main navigation"
      >
        <a href="#hero" className="flex items-center gap-2 focus-ring rounded-lg">
          <img src={logo} alt="Amine Abbaoui" className="h-8 w-auto" />
        </a>

        <ul className="hidden lg:flex items-center gap-8">
          {links.map(({ href, key }) => (
            <li key={href}>
              <a
                href={href}
                className="text-sm text-zinc-400 hover:text-accent-cyan transition-colors focus-ring rounded"
              >
                {t(key)}
              </a>
            </li>
          ))}
        </ul>

        <div className="hidden lg:flex items-center gap-4">
          <LanguageSwitcher lang={lang} onLangChange={onLangChange} />
        </div>

        <button
          type="button"
          className="lg:hidden p-2 text-zinc-300 focus-ring rounded-lg"
          onClick={() => setOpen(!open)}
          aria-expanded={open}
          aria-label="Toggle menu"
        >
          {open ? <X size={24} /> : <Menu size={24} />}
        </button>
      </nav>

      {open && (
        <div className="lg:hidden glass-panel mx-4 mt-2 p-4 rounded-xl border border-white/10">
          <ul className="flex flex-col gap-3">
            {links.map(({ href, key }) => (
              <li key={href}>
                <a
                  href={href}
                  className="block py-2 text-zinc-300 hover:text-accent-cyan"
                  onClick={() => setOpen(false)}
                >
                  {t(key)}
                </a>
              </li>
            ))}
          </ul>
          <div className="mt-4 pt-4 border-t border-white/10">
            <LanguageSwitcher lang={lang} onLangChange={onLangChange} />
          </div>
        </div>
      )}
    </header>
  );
}
