export function localized(item, lang, field) {
  const l = lang === 'ar' ? 'ar' : lang === 'fr' ? 'fr' : 'en';
  const key = `${field}_${l}`;
  return item[key] || item[`${field}_en`] || '';
}

export function localizedList(items, lang, field) {
  return items.map((item) => localized(item, lang, field));
}
