import React from 'react';
import { motion } from '../ui/motion';
import { useTranslation } from 'react-i18next';
import { ArrowRight, Sparkles } from '../ui/icons';
import profile from '../../content/profile.json';
import techStack from '../../content/tech-stack.json';
import { localized } from '../../utils/content';
import { useTypingEffect } from '../../hooks/useTypingEffect';
import Button from '../ui/Button';
import Badge from '../ui/Badge';
import GridBackground from '../ui/GridBackground';
import GlowOrb from '../ui/GlowOrb';
import heroImg from '../../img/template-homepage.jpg';

export default function HeroSection({ lang }) {
  const { t } = useTranslation();
  const l = lang === 'ar' ? 'ar' : lang === 'fr' ? 'fr' : 'en';
  const phrases = profile[`typing_${l}`] || profile.typing_en;
  const typed = useTypingEffect(phrases, 45, 2200);

  const topTech = techStack.categories
    .flatMap((c) => c.items)
    .slice(0, 6)
    .map((i) => i.name);

  return (
    <section
      id="hero"
      className="relative min-h-screen flex items-center pt-24 pb-16 overflow-hidden gradient-mesh"
    >
      <GridBackground />
      <GlowOrb className="w-96 h-96 -top-20 -left-20" color="blue" />
      <GlowOrb className="w-80 h-80 top-1/3 right-0" color="purple" />
      <GlowOrb className="w-64 h-64 bottom-10 left-1/3" color="cyan" />

      <div className="section-container relative z-10 grid lg:grid-cols-2 gap-12 items-center">
        <motion.div
          initial={{ opacity: 0, x: -24 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.6 }}
        >
          <div className="flex items-center gap-2 mb-6">
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75" />
              <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500" />
            </span>
            <span className="font-mono text-sm text-green-400">
              {localized(profile, lang, 'availability')}
            </span>
          </div>

          <p className="font-mono text-accent-cyan text-sm mb-2 flex items-center gap-2">
            <Sparkles size={14} />
            {localized(profile, lang, 'title')}
          </p>

          <h1 className="text-4xl sm:text-5xl lg:text-6xl font-bold mb-4 tracking-tight">
            {profile.name}
          </h1>

          <p className="text-xl text-zinc-400 mb-2 h-8 font-mono">
            {typed}
            <span className="animate-pulse text-accent-cyan">|</span>
          </p>

          <p className="text-lg text-zinc-500 mb-8 max-w-xl">
            {localized(profile, lang, 'tagline')}
          </p>

          <div className="flex flex-wrap gap-3 mb-8">
            <Button href="#projects" variant="primary">
              {t('ctaProjects')} <ArrowRight size={16} />
            </Button>
            <Button href={profile.blog} variant="secondary">
              {t('ctaBlog')}
            </Button>
            <Button href="#contact" variant="ghost">
              {t('ctaContact')}
            </Button>
          </div>

          <div className="flex flex-wrap gap-4 text-sm text-zinc-500 font-mono mb-8">
            <span>{profile.yearsExperience}+ {t('yearsExp')}</span>
            <span>·</span>
            <span>{localized(profile, lang, 'currentFocus')}</span>
          </div>

          <div className="flex flex-wrap gap-2">
            {topTech.map((name) => (
              <Badge key={name}>{name}</Badge>
            ))}
          </div>
        </motion.div>

        <motion.div
          className="relative flex justify-center lg:justify-end"
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.6, delay: 0.2 }}
        >
          <div className="relative">
            <motion.div
              className="absolute inset-0 rounded-full bg-gradient-to-tr from-accent-cyan/40 to-accent-purple/30 blur-2xl scale-110"
              aria-hidden="true"
            />
            <img
              src={heroImg}
              alt={profile.name}
              className="relative w-64 h-64 sm:w-80 sm:h-80 rounded-2xl object-cover border border-white/10 shadow-glow-lg"
              loading="eager"
            />
          </div>
        </motion.div>
      </div>
    </section>
  );
}
