import React, { useState, useEffect } from 'react';
import AppShell from '../components/layout/AppShell';
import HeroSection from '../components/sections/HeroSection';
import AboutSection from '../components/sections/AboutSection';
import TechStackSection from '../components/sections/TechStackSection';
import FeaturedProjectsSection from '../components/sections/FeaturedProjectsSection';
import ContentSection from '../components/sections/ContentSection';
import JourneySection from '../components/sections/JourneySection';
import CertificationsSection from '../components/sections/CertificationsSection';
import ProductsSection from '../components/sections/ProductsSection';
import ContactSection from '../components/sections/ContactSection';
import profile from '../content/profile.json';
import '../styles/globals.css';

export default function HomePage() {
  const [lang, setLang] = useState('en');

  useEffect(() => {
    document.documentElement.classList.add('dark');
    document.title = `${profile.name} — Senior Software Engineer`;
    const meta = document.querySelector('meta[name="description"]');
    if (meta) {
      meta.setAttribute(
        'content',
        'Senior Software Engineer specializing in scalable systems, cloud architecture, APIs, and developer tools.'
      );
    }
  }, []);

  return (
    <AppShell lang={lang} onLangChange={setLang}>
      <HeroSection lang={lang} />
      <AboutSection lang={lang} />
      <TechStackSection lang={lang} />
      <FeaturedProjectsSection lang={lang} />
      <ContentSection lang={lang} />
      <JourneySection lang={lang} />
      <CertificationsSection lang={lang} />
      <ProductsSection lang={lang} />
      <ContactSection lang={lang} />
    </AppShell>
  );
}
